INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Lernfeld 1 > Software > Konfiguration und Inbetriebnahme > Betriebssysteme > Windows
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Kann Windows ohne Rücksicht auf die Hardwarevoraussetzungen installiert werden?', 2, '[{"text": "Nein", "correct": true, "because": "Hardware muss Mindestanforderungen erfüllen"}, {"text": "Ja", "correct": false, "because": "Inkompatibilität verhindert Installation"}]'),
('00000000-0000-0000-0000-000000000000', 'Müssen bei der Konfiguration von Windows immer Benutzerkonten erstellt werden?', 2, '[{"text": "Ja", "correct": true, "because": "Erforderlich für Zugriff und Sicherheit"}, {"text": "Nein", "correct": false, "because": "Standardprozess"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist eine Internetverbindung während der Windows-Installation zwingend erforderlich?', 2, '[{"text": "Nein", "correct": true, "because": "Offline-Installation möglich"}, {"text": "Ja", "correct": false, "because": "Nur für Updates nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Können Windows-Einstellungen nach der Inbetriebnahme nicht mehr geändert werden?', 2, '[{"text": "Nein", "correct": true, "because": "Einstellungen sind anpassbar"}, {"text": "Ja", "correct": false, "because": "Änderungen möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist Windows immer vorinstalliert auf neuen Computern?', 2, '[{"text": "Nein", "correct": true, "because": "Manche Geräte ohne Betriebssystem"}, {"text": "Ja", "correct": false, "because": "Nicht zwingend vorinstalliert"}]'),
-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welcher Schritt ist bei der Windows-Installation am wichtigsten?', 3, '[{"text": "Festlegung der Partitionen", "correct": true, "because": "Definiert Speicheraufteilung"}, {"text": "Farbauswahl", "correct": false, "because": "Ästhetisch, nicht funktional"}, {"text": "Installation von Spielen", "correct": false, "because": "Nachgelagert"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Mindestanforderung ist für Windows 11 entscheidend?', 2, '[{"text": "TPM 2.0", "correct": true, "because": "Sicherheitsanforderung"}, {"text": "1 GB RAM", "correct": false, "because": "Zu wenig"}, {"text": "32-Bit-Prozessor", "correct": false, "because": "Nur 64-Bit unterstützt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Tool wird zur Windows-Konfiguration nach der Installation verwendet?', 2, '[{"text": "Systemsteuerung", "correct": true, "because": "Ermöglicht umfassende Einstellungen"}, {"text": "Notepad", "correct": false, "because": "Texteditor"}, {"text": "Browser", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Edition von Windows ist für Unternehmen typisch?', 3, '[{"text": "Windows Enterprise", "correct": true, "because": "Erweiterte Funktionen für Firmen"}, {"text": "Windows Home", "correct": false, "because": "Für Privatnutzer"}, {"text": "Windows Education", "correct": false, "because": "Für Bildungsbereich"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist ein Hauptvorteil der Windows-Konfiguration?', 2, '[{"text": "Benutzerfreundlichkeit", "correct": true, "because": "Intuitive Oberfläche"}, {"text": "Kostenlos", "correct": false, "because": "Lizenz erforderlich"}, {"text": "Hardwareunabhängig", "correct": false, "because": "Hardwareabhängig"}]'),
-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Schritte gehören zur Windows-Installation?', 4, '[{"text": "Festplattenpartitionierung", "correct": true, "because": "Speicheraufteilung"}, {"text": "Lizenzschlüssel eingeben", "correct": true, "because": "Aktivierung erforderlich"}, {"text": "Treiberinstallation", "correct": true, "because": "Hardwarefunktion sichern"}, {"text": "Spiele installieren", "correct": false, "because": "Nachgelagert"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Hardwareanforderungen sind für Windows wichtig?', 3, '[{"text": "Prozessorleistung", "correct": true, "because": "Mindestgeschwindigkeit nötig"}, {"text": "Arbeitsspeicher", "correct": true, "because": "Für flüssige Nutzung"}, {"text": "Festplattenspeicher", "correct": true, "because": "Für Installation"}, {"text": "Monitorfarbe", "correct": false, "because": "Ästhetisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Probleme können bei der Windows-Konfiguration auftreten?', 3, '[{"text": "Inkompatible Hardware", "correct": true, "because": "Verhindert Installation"}, {"text": "Fehlende Treiber", "correct": true, "because": "Beeinträchtigt Funktion"}, {"text": "Ungültiger Lizenzschlüssel", "correct": true, "because": "Blockiert Aktivierung"}, {"text": "Falsche Farbeinstellung", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Tools helfen bei der Windows-Konfiguration?', 4, '[{"text": "Systemsteuerung", "correct": true, "because": "Einstellungen anpassen"}, {"text": "Einstellungen-App", "correct": true, "because": "Moderne Konfiguration"}, {"text": "Geräte-Manager", "correct": true, "because": "Hardwareverwaltung"}, {"text": "Paint", "correct": false, "because": "Grafikprogramm"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet die Windows-Inbetriebnahme?', 3, '[{"text": "Breite Hardwareunterstützung", "correct": true, "because": "Kompatibel mit vielen Geräten"}, {"text": "Benutzerfreundliche Oberfläche", "correct": true, "because": "Einfache Bedienung"}, {"text": "Automatische Updates", "correct": true, "because": "Sicherheit und Funktionen"}, {"text": "Kostenlos", "correct": false, "because": "Lizenzgebühren nötig"}]'),
-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Windows erfordert einen Lizenzschlüssel für die Installation. b) Eine Internetverbindung ist für die Installation zwingend nötig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Lizenz ja, Internet optional"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Die Systemsteuerung hilft bei der Windows-Konfiguration. b) Windows kann ohne Benutzerkonto genutzt werden.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Systemsteuerung ja, Konto nötig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) TPM 2.0 ist eine Voraussetzung für Windows 11. b) Windows-Einstellungen sind nach Installation unveränderbar.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "TPM ja, Einstellungen anpassbar"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Windows Enterprise ist für Unternehmen geeignet. b) Treiberinstallation ist bei der Inbetriebnahme unwichtig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Enterprise ja, Treiber wichtig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Windows bietet automatische Updates. b) Die Partitionierung ist bei der Installation optional.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Updates ja, Partitionierung nötig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

